"""
Port interfaces (abstract contracts) for all infrastructure adapters.

Every concrete adapter — regardless of profile — implements exactly
these interfaces.  Business logic depends only on these ports.
"""

from __future__ import annotations

import abc
from typing import Any, Optional


class ObjectStoragePort(abc.ABC):
    """Contract for object/blob storage (S3, MinIO, etc.)."""

    @abc.abstractmethod
    def put_object(self, bucket: str, key: str, data: bytes) -> None:
        """Store *data* under *bucket*/*key*."""

    @abc.abstractmethod
    def get_object(self, bucket: str, key: str) -> bytes:
        """Return the raw bytes stored at *bucket*/*key*.

        Raises ``KeyError`` when the object does not exist.
        """

    @abc.abstractmethod
    def delete_object(self, bucket: str, key: str) -> None:
        """Delete the object at *bucket*/*key*.

        Idempotent — does not raise if the object is already absent.
        """

    @abc.abstractmethod
    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        """Return keys in *bucket* matching *prefix*."""


class QueuePort(abc.ABC):
    """Contract for message queue (SQS, RabbitMQ, Redis Streams, etc.)."""

    @abc.abstractmethod
    def send_message(self, queue_name: str, body: str, attributes: Optional[dict[str, str]] = None) -> str:
        """Enqueue a message.  Return a message-id."""

    @abc.abstractmethod
    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]:
        """Receive up to *max_messages*.

        Each dict contains at least ``message_id``, ``body``, and
        ``receipt_handle``.
        """

    @abc.abstractmethod
    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        """Acknowledge / delete a received message."""


class EventingPort(abc.ABC):
    """Contract for pub/sub eventing (SNS, NATS, Redis Pub/Sub, etc.)."""

    @abc.abstractmethod
    def publish(self, topic: str, message: str, attributes: Optional[dict[str, str]] = None) -> str:
        """Publish *message* to *topic*.  Return a message/event id."""

    @abc.abstractmethod
    def subscribe(self, topic: str, callback_url_or_queue: str) -> str:
        """Subscribe *callback_url_or_queue* to *topic*.  Return subscription id."""


class SecretsPort(abc.ABC):
    """Contract for secrets management (Secrets Manager, Vault, etc.)."""

    @abc.abstractmethod
    def get_secret(self, secret_id: str) -> str:
        """Return the plaintext value of *secret_id*.

        Raises ``KeyError`` when the secret does not exist.
        """

    @abc.abstractmethod
    def put_secret(self, secret_id: str, value: str) -> None:
        """Create or update *secret_id* with *value*."""


class LogSinkPort(abc.ABC):
    """Contract for structured log sink (CloudWatch, Loki, file, etc.)."""

    @abc.abstractmethod
    def emit(self, log_entry: dict[str, Any]) -> None:
        """Send a structured log entry to the sink."""

    @abc.abstractmethod
    def flush(self) -> None:
        """Flush any buffered entries."""

"""AWS (S3) object-storage adapter."""

from __future__ import annotations

from typing import Any, Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import ObjectStoragePort


class S3ObjectStorage(ObjectStoragePort):
    """Adapter backed by Amazon S3 (or any S3-compatible endpoint such as LocalStack)."""

    def __init__(
        self,
        *,
        endpoint_url: Optional[str] = None,
        region_name: str = "us-east-1",
        aws_access_key_id: Optional[str] = None,
        aws_secret_access_key: Optional[str] = None,
    ) -> None:
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        if aws_access_key_id:
            kwargs["aws_access_key_id"] = aws_access_key_id
        if aws_secret_access_key:
            kwargs["aws_secret_access_key"] = aws_secret_access_key
        self._client = boto3.client("s3", **kwargs)

    # -- helpers ----------------------------------------------------------

    def _ensure_bucket(self, bucket: str) -> None:
        """Create the bucket if it does not exist (idempotent)."""
        try:
            self._client.head_bucket(Bucket=bucket)
        except ClientError:
            try:
                self._client.create_bucket(Bucket=bucket)
            except ClientError:
                pass  # may already exist in race

    # -- port implementation ----------------------------------------------

    def put_object(self, bucket: str, key: str, data: bytes) -> None:
        self._ensure_bucket(bucket)
        self._client.put_object(Bucket=bucket, Key=key, Body=data)

    def get_object(self, bucket: str, key: str) -> bytes:
        try:
            resp = self._client.get_object(Bucket=bucket, Key=key)
            return resp["Body"].read()
        except ClientError as exc:
            code = exc.response.get("Error", {}).get("Code", "")
            if code in ("NoSuchKey", "404", "NoSuchBucket"):
                raise KeyError(f"{bucket}/{key}") from exc
            raise

    def delete_object(self, bucket: str, key: str) -> None:
        try:
            self._client.delete_object(Bucket=bucket, Key=key)
        except ClientError:
            pass  # idempotent

    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        try:
            resp = self._client.list_objects_v2(Bucket=bucket, Prefix=prefix)
            return [obj["Key"] for obj in resp.get("Contents", [])]
        except ClientError:
            return []

"""AWS (SQS) queue adapter."""

from __future__ import annotations

from typing import Any, Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import QueuePort


class SQSQueue(QueuePort):
    """Adapter backed by Amazon SQS (or LocalStack SQS)."""

    def __init__(
        self,
        *,
        endpoint_url: Optional[str] = None,
        region_name: str = "us-east-1",
        aws_access_key_id: Optional[str] = None,
        aws_secret_access_key: Optional[str] = None,
    ) -> None:
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        if aws_access_key_id:
            kwargs["aws_access_key_id"] = aws_access_key_id
        if aws_secret_access_key:
            kwargs["aws_secret_access_key"] = aws_secret_access_key
        self._client = boto3.client("sqs", **kwargs)
        self._url_cache: dict[str, str] = {}

    def _queue_url(self, queue_name: str) -> str:
        if queue_name not in self._url_cache:
            try:
                resp = self._client.get_queue_url(QueueName=queue_name)
                self._url_cache[queue_name] = resp["QueueUrl"]
            except ClientError:
                resp = self._client.create_queue(QueueName=queue_name)
                self._url_cache[queue_name] = resp["QueueUrl"]
        return self._url_cache[queue_name]

    def send_message(self, queue_name: str, body: str, attributes: Optional[dict[str, str]] = None) -> str:
        msg_attrs: dict[str, Any] = {}
        if attributes:
            msg_attrs = {
                k: {"StringValue": v, "DataType": "String"} for k, v in attributes.items()
            }
        resp = self._client.send_message(
            QueueUrl=self._queue_url(queue_name),
            MessageBody=body,
            MessageAttributes=msg_attrs,
        )
        return resp["MessageId"]

    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]:
        resp = self._client.receive_message(
            QueueUrl=self._queue_url(queue_name),
            MaxNumberOfMessages=min(max_messages, 10),
            WaitTimeSeconds=wait_seconds,
        )
        results: list[dict[str, Any]] = []
        for msg in resp.get("Messages", []):
            results.append({
                "message_id": msg["MessageId"],
                "body": msg["Body"],
                "receipt_handle": msg["ReceiptHandle"],
            })
        return results

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        self._client.delete_message(
            QueueUrl=self._queue_url(queue_name),
            ReceiptHandle=receipt_handle,
        )

"""AWS (SNS) eventing adapter."""

from __future__ import annotations

from typing import Any, Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import EventingPort


class SNSEventing(EventingPort):
    """Adapter backed by Amazon SNS (or LocalStack SNS)."""

    def __init__(
        self,
        *,
        endpoint_url: Optional[str] = None,
        region_name: str = "us-east-1",
        aws_access_key_id: Optional[str] = None,
        aws_secret_access_key: Optional[str] = None,
    ) -> None:
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        if aws_access_key_id:
            kwargs["aws_access_key_id"] = aws_access_key_id
        if aws_secret_access_key:
            kwargs["aws_secret_access_key"] = aws_secret_access_key
        self._client = boto3.client("sns", **kwargs)
        self._arn_cache: dict[str, str] = {}

    def _topic_arn(self, topic: str) -> str:
        if topic not in self._arn_cache:
            resp = self._client.create_topic(Name=topic)
            self._arn_cache[topic] = resp["TopicArn"]
        return self._arn_cache[topic]

    def publish(self, topic: str, message: str, attributes: Optional[dict[str, str]] = None) -> str:
        msg_attrs: dict[str, Any] = {}
        if attributes:
            msg_attrs = {
                k: {"StringValue": v, "DataType": "String"} for k, v in attributes.items()
            }
        resp = self._client.publish(
            TopicArn=self._topic_arn(topic),
            Message=message,
            MessageAttributes=msg_attrs,
        )
        return resp["MessageId"]

    def subscribe(self, topic: str, callback_url_or_queue: str) -> str:
        protocol = "https" if callback_url_or_queue.startswith("http") else "sqs"
        resp = self._client.subscribe(
            TopicArn=self._topic_arn(topic),
            Protocol=protocol,
            Endpoint=callback_url_or_queue,
        )
        return resp["SubscriptionArn"]

"""AWS (Secrets Manager) secrets adapter."""

from __future__ import annotations

from typing import Any, Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import SecretsPort


class SMSecrets(SecretsPort):
    """Adapter backed by AWS Secrets Manager (or LocalStack)."""

    def __init__(
        self,
        *,
        endpoint_url: Optional[str] = None,
        region_name: str = "us-east-1",
        aws_access_key_id: Optional[str] = None,
        aws_secret_access_key: Optional[str] = None,
    ) -> None:
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        if aws_access_key_id:
            kwargs["aws_access_key_id"] = aws_access_key_id
        if aws_secret_access_key:
            kwargs["aws_secret_access_key"] = aws_secret_access_key
        self._client = boto3.client("secretsmanager", **kwargs)

    def get_secret(self, secret_id: str) -> str:
        try:
            resp = self._client.get_secret_value(SecretId=secret_id)
            return resp["SecretString"]
        except ClientError as exc:
            code = exc.response.get("Error", {}).get("Code", "")
            if code == "ResourceNotFoundException":
                raise KeyError(secret_id) from exc
            raise

    def put_secret(self, secret_id: str, value: str) -> None:
        try:
            self._client.create_secret(Name=secret_id, SecretString=value)
        except ClientError as exc:
            code = exc.response.get("Error", {}).get("Code", "")
            if code == "ResourceAlreadyExistsException":
                self._client.put_secret_value(SecretId=secret_id, SecretString=value)
            else:
                raise

"""AWS (CloudWatch Logs) log-sink adapter."""

from __future__ import annotations

import json
import time
from typing import Any, Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import LogSinkPort


class CloudWatchLogSink(LogSinkPort):
    """Adapter backed by CloudWatch Logs (or LocalStack)."""

    def __init__(
        self,
        *,
        log_group: str = "/app/default",
        log_stream: str = "default",
        endpoint_url: Optional[str] = None,
        region_name: str = "us-east-1",
        aws_access_key_id: Optional[str] = None,
        aws_secret_access_key: Optional[str] = None,
    ) -> None:
        kwargs: dict[str, Any] = {"region_name": region_name}
        if endpoint_url:
            kwargs["endpoint_url"] = endpoint_url
        if aws_access_key_id:
            kwargs["aws_access_key_id"] = aws_access_key_id
        if aws_secret_access_key:
            kwargs["aws_secret_access_key"] = aws_secret_access_key
        self._client = boto3.client("logs", **kwargs)
        self._log_group = log_group
        self._log_stream = log_stream
        self._buffer: list[dict[str, Any]] = []
        self._sequence_token: Optional[str] = None
        self._ensure_group_and_stream()

    def _ensure_group_and_stream(self) -> None:
        try:
            self._client.create_log_group(logGroupName=self._log_group)
        except ClientError:
            pass
        try:
            self._client.create_log_stream(
                logGroupName=self._log_group, logStreamName=self._log_stream
            )
        except ClientError:
            pass

    def emit(self, log_entry: dict[str, Any]) -> None:
        self._buffer.append(log_entry)
        if len(self._buffer) >= 25:
            self.flush()

    def flush(self) -> None:
        if not self._buffer:
            return
        events = [
            {
                "timestamp": int(time.time() * 1000),
                "message": json.dumps(entry),
            }
            for entry in self._buffer
        ]
        kwargs: dict[str, Any] = {
            "logGroupName": self._log_group,
            "logStreamName": self._log_stream,
            "logEvents": events,
        }
        if self._sequence_token:
            kwargs["sequenceToken"] = self._sequence_token
        try:
            resp = self._client.put_log_events(**kwargs)
            self._sequence_token = resp.get("nextSequenceToken")
        except ClientError:
            pass  # best-effort log delivery
        self._buffer.clear()

"""On-prem (MinIO / S3-compatible) object-storage adapter."""

from __future__ import annotations

import os
from typing import Any, Optional

import boto3
from botocore.exceptions import ClientError

from shared.adapters.ports import ObjectStoragePort


class MinIOObjectStorage(ObjectStoragePort):
    """Adapter backed by MinIO or any S3-compatible on-prem store.

    Uses the same boto3 S3 client with a configurable endpoint.
    """

    def __init__(
        self,
        *,
        endpoint_url: Optional[str] = None,
        region_name: str = "us-east-1",
        aws_access_key_id: Optional[str] = None,
        aws_secret_access_key: Optional[str] = None,
    ) -> None:
        self._endpoint_url = endpoint_url or os.environ.get(
            "MINIO_ENDPOINT_URL", "http://localhost:9000"
        )
        kwargs: dict[str, Any] = {
            "region_name": region_name,
            "endpoint_url": self._endpoint_url,
            "aws_access_key_id": aws_access_key_id or os.environ.get("MINIO_ACCESS_KEY", "minioadmin"),
            "aws_secret_access_key": aws_secret_access_key or os.environ.get("MINIO_SECRET_KEY", "minioadmin"),
        }
        self._client = boto3.client("s3", **kwargs)

    def _ensure_bucket(self, bucket: str) -> None:
        try:
            self._client.head_bucket(Bucket=bucket)
        except ClientError:
            try:
                self._client.create_bucket(Bucket=bucket)
            except ClientError:
                pass

    def put_object(self, bucket: str, key: str, data: bytes) -> None:
        self._ensure_bucket(bucket)
        self._client.put_object(Bucket=bucket, Key=key, Body=data)

    def get_object(self, bucket: str, key: str) -> bytes:
        try:
            resp = self._client.get_object(Bucket=bucket, Key=key)
            return resp["Body"].read()
        except ClientError as exc:
            code = exc.response.get("Error", {}).get("Code", "")
            if code in ("NoSuchKey", "404", "NoSuchBucket"):
                raise KeyError(f"{bucket}/{key}") from exc
            raise

    def delete_object(self, bucket: str, key: str) -> None:
        try:
            self._client.delete_object(Bucket=bucket, Key=key)
        except ClientError:
            pass

    def list_objects(self, bucket: str, prefix: str = "") -> list[str]:
        try:
            resp = self._client.list_objects_v2(Bucket=bucket, Prefix=prefix)
            return [obj["Key"] for obj in resp.get("Contents", [])]
        except ClientError:
            return []

"""On-prem queue adapter backed by Redis Streams."""

from __future__ import annotations

import json
import os
import uuid
from typing import Any, Optional

import redis

from shared.adapters.ports import QueuePort


class RedisQueue(QueuePort):
    """Queue adapter using Redis Streams for on-prem deployments."""

    def __init__(
        self,
        *,
        redis_url: Optional[str] = None,
        consumer_group: str = "default-group",
        consumer_name: Optional[str] = None,
    ) -> None:
        url = redis_url or os.environ.get("REDIS_URL", "redis://localhost:6379/0")
        self._redis = redis.Redis.from_url(url, decode_responses=True)
        self._consumer_group = consumer_group
        self._consumer_name = consumer_name or f"consumer-{uuid.uuid4().hex[:8]}"

    def _ensure_group(self, queue_name: str) -> None:
        try:
            self._redis.xgroup_create(queue_name, self._consumer_group, id="0", mkstream=True)
        except redis.ResponseError as exc:
            if "BUSYGROUP" not in str(exc):
                raise

    def send_message(self, queue_name: str, body: str, attributes: Optional[dict[str, str]] = None) -> str:
        payload: dict[str, str] = {"body": body}
        if attributes:
            payload["attributes"] = json.dumps(attributes)
        msg_id: str = self._redis.xadd(queue_name, payload)  # type: ignore[assignment]
        return msg_id

    def receive_messages(self, queue_name: str, max_messages: int = 1, wait_seconds: int = 0) -> list[dict[str, Any]]:
        self._ensure_group(queue_name)
        block_ms = wait_seconds * 1000 if wait_seconds > 0 else None
        raw = self._redis.xreadgroup(
            groupname=self._consumer_group,
            consumername=self._consumer_name,
            streams={queue_name: ">"},
            count=max_messages,
            block=block_ms,
        )
        results: list[dict[str, Any]] = []
        if raw:
            for _stream, messages in raw:
                for msg_id, fields in messages:
                    results.append({
                        "message_id": msg_id,
                        "body": fields.get("body", ""),
                        "receipt_handle": msg_id,
                    })
        return results

    def delete_message(self, queue_name: str, receipt_handle: str) -> None:
        self._redis.xack(queue_name, self._consumer_group, receipt_handle)

"""
AdapterRegistry — profile-aware adapter factory.

Reads ``DEPLOYMENT_PROFILE`` from the environment and returns the
correct concrete adapter for each port.  Business code never imports
concrete adapters directly; it calls ``get_registry()`` and uses the
port accessors.
"""

from __future__ import annotations

import os
from typing import Any, Optional

from shared.adapters.adapter_contract import (
    VALID_PROFILES,
    ProfileError,
    resolve_profile,
    validate_registry,
)
from shared.adapters.ports import (
    EventingPort,
    LogSinkPort,
    ObjectStoragePort,
    QueuePort,
    SecretsPort,
)


class AdapterRegistry:
    """Lazy, profile-aware adapter registry.

    Adapters are instantiated on first access and cached for the
    lifetime of the registry instance.
    """

    def __init__(self, profile: Optional[str] = None, **overrides: Any) -> None:
        self._profile = profile or resolve_profile()
        self._overrides = overrides
        self._cache: dict[str, Any] = {}

    @property
    def profile(self) -> str:
        return self._profile

    # -- AWS factories ----------------------------------------------------

    def _aws_common_kwargs(self) -> dict[str, Any]:
        return {
            "endpoint_url": os.environ.get("AWS_ENDPOINT_URL"),
            "region_name": os.environ.get("AWS_DEFAULT_REGION", "us-east-1"),
            "aws_access_key_id": os.environ.get("AWS_ACCESS_KEY_ID"),
            "aws_secret_access_key": os.environ.get("AWS_SECRET_ACCESS_KEY"),
        }

    def _aws_object_storage(self) -> ObjectStoragePort:
        from shared.adapters.aws.object_storage import S3ObjectStorage
        return S3ObjectStorage(**self._aws_common_kwargs())

    def _aws_queue(self) -> QueuePort:
        from shared.adapters.aws.queue import SQSQueue
        return SQSQueue(**self._aws_common_kwargs())

    def _aws_eventing(self) -> EventingPort:
        from shared.adapters.aws.eventing import SNSEventing
        return SNSEventing(**self._aws_common_kwargs())

    def _aws_secrets(self) -> SecretsPort:
        from shared.adapters.aws.secrets import SMSecrets
        return SMSecrets(**self._aws_common_kwargs())

    def _aws_log_sink(self) -> LogSinkPort:
        from shared.adapters.aws.log_sink import CloudWatchLogSink
        kwargs = self._aws_common_kwargs()
        kwargs["log_group"] = os.environ.get("LOG_GROUP", "/app/default")
        kwargs["log_stream"] = os.environ.get("LOG_STREAM", "default")
        return CloudWatchLogSink(**kwargs)

    # -- On-prem factories ------------------------------------------------

    def _onprem_object_storage(self) -> ObjectStoragePort:
        from shared.adapters.onprem.object_storage import MinIOObjectStorage
        return MinIOObjectStorage(
            endpoint_url=os.environ.get("MINIO_ENDPOINT_URL", "http://localhost:9000"),
            aws_access_key_id=os.environ.get("MINIO_ACCESS_KEY", "minioadmin"),
            aws_secret_access_key=os.environ.get("MINIO_SECRET_KEY", "minioadmin"),
        )

    def _onprem_queue(self) -> QueuePort:
        from shared.adapters.onprem.queue import RedisQueue
        return RedisQueue(redis_url=os.environ.get("REDIS_URL", "redis://localhost:6379/0"))

    def _onprem_eventing(self) -> EventingPort:
        from shared.adapters.onprem.eventing import RedisEventing
        return RedisEventing(redis_url=os.environ.get("REDIS_URL", "redis://localhost:6379/0"))

    def _onprem_secrets(self) -> SecretsPort:
        from shared.adapters.onprem.secrets import EnvFileSecrets
        return EnvFileSecrets()

    def _onprem_log_sink(self) -> LogSinkPort:
        from shared.adapters.onprem.log_sink import FileLogSink
        return FileLogSink(log_file=os.environ.get("LOG_SINK_FILE"))

    # -- Profile dispatch table -------------------------------------------

    _FACTORY_MAP: dict[str, dict[str, str]] = {
        "aws": {
            "object_storage": "_aws_object_storage",
            "queue": "_aws_queue",
            "eventing": "_aws_eventing",
            "secrets": "_aws_secrets",
            "log_sink": "_aws_log_sink",
        },
        "onprem": {
            "object_storage": "_onprem_object_storage",
            "queue": "_onprem_queue",
            "eventing": "_onprem_eventing",
            "secrets": "_onprem_secrets",
            "log_sink": "_onprem_log_sink",
        },
    }

    def _get(self, port_name: str) -> Any:
        if port_name in self._cache:
            return self._cache[port_name]
        factories = self._FACTORY_MAP.get(self._profile)
        if factories is None:
            raise ProfileError(f"No factories registered for profile '{self._profile}'")
        method_name = factories.get(port_name)
        if method_name is None:
            raise ProfileError(
                f"No factory for port '{port_name}' in profile '{self._profile}'"
            )
        instance = getattr(self, method_name)()
        self._cache[port_name] = instance
        return instance

    # -- Public port accessors --------------------------------------------

    def object_storage(self) -> ObjectStoragePort:
        return self._get("object_storage")

    def queue(self) -> QueuePort:
        return self._get("queue")

    def eventing(self) -> EventingPort:
        return self._get("eventing")

    def secrets(self) -> SecretsPort:
        return self._get("secrets")

    def log_sink(self) -> LogSinkPort:
        return self._get("log_sink")

    def validate(self) -> None:
        """Run parity validation on this registry."""
        validate_registry(self)


# -- Module-level convenience -------------------------------------------

_default_registry: Optional[AdapterRegistry] = None


def get_registry(*, force_new: bool = False) -> AdapterRegistry:
    """Return a module-level singleton ``AdapterRegistry``.

    Set ``force_new=True`` to discard the cached instance (useful in tests).
    """
    global _default_registry
    if _default_registry is None or force_new:
        _default_registry = AdapterRegistry()
    return _default_registry

