"""
Adapter contract validation and profile parity rules.

This module provides:
  - ``VALID_PROFILES``: the set of recognised deployment profiles.
  - ``REQUIRED_PORT_NAMES``: the port names every profile must supply.
  - ``validate_registry``: runtime check that a registry satisfies parity.
  - ``resolve_profile``: read and validate DEPLOYMENT_PROFILE from env.
"""

from __future__ import annotations

import os
from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from shared.adapters.registry import AdapterRegistry

VALID_PROFILES: frozenset[str] = frozenset({"aws", "onprem"})

REQUIRED_PORT_NAMES: frozenset[str] = frozenset({
    "object_storage",
    "queue",
    "eventing",
    "secrets",
    "log_sink",
})

# Maps port name → expected abstract base class path (for docs / introspection)
PORT_INTERFACE_MAP: dict[str, str] = {
    "object_storage": "shared.adapters.ports.ObjectStoragePort",
    "queue": "shared.adapters.ports.QueuePort",
    "eventing": "shared.adapters.ports.EventingPort",
    "secrets": "shared.adapters.ports.SecretsPort",
    "log_sink": "shared.adapters.ports.LogSinkPort",
}


class ProfileError(Exception):
    """Raised when the deployment profile is missing or invalid."""


class AdapterParityError(Exception):
    """Raised when a profile registry does not satisfy parity rules."""


def resolve_profile(*, env_var: str = "DEPLOYMENT_PROFILE") -> str:
    """Read and validate the deployment profile from the environment.

    Returns the lower-cased profile name.

    Raises ``ProfileError`` when the variable is unset, empty, or not
    one of the recognised profiles.
    """
    raw = os.environ.get(env_var, "").strip().lower()
    if not raw:
        raise ProfileError(
            f"Environment variable {env_var} is not set or empty. "
            f"Valid profiles: {sorted(VALID_PROFILES)}"
        )
    if raw not in VALID_PROFILES:
        raise ProfileError(
            f"Unknown deployment profile '{raw}'. "
            f"Valid profiles: {sorted(VALID_PROFILES)}"
        )
    return raw


def validate_registry(registry: "AdapterRegistry") -> None:
    """Assert that *registry* exposes every required port.

    Raises ``AdapterParityError`` with details on missing ports.
    """
    from shared.adapters.ports import (
        ObjectStoragePort,
        QueuePort,
        EventingPort,
        SecretsPort,
        LogSinkPort,
    )

    port_type_map: dict[str, type] = {
        "object_storage": ObjectStoragePort,
        "queue": QueuePort,
        "eventing": EventingPort,
        "secrets": SecretsPort,
        "log_sink": LogSinkPort,
    }

    missing: list[str] = []
    wrong_type: list[str] = []

    for port_name in sorted(REQUIRED_PORT_NAMES):
        accessor = getattr(registry, port_name, None)
        if accessor is None:
            missing.append(port_name)
            continue
        try:
            instance = accessor()
        except Exception as exc:
            missing.append(f"{port_name} (factory raised {exc!r})")
            continue
        expected_type = port_type_map[port_name]
        if not isinstance(instance, expected_type):
            wrong_type.append(
                f"{port_name}: expected {expected_type.__name__}, "
                f"got {type(instance).__name__}"
            )

    errors: list[str] = []
    if missing:
        errors.append(f"Missing ports: {missing}")
    if wrong_type:
        errors.append(f"Type mismatches: {wrong_type}")
    if errors:
        raise AdapterParityError(
            f"Registry for profile '{registry.profile}' failed parity: "
            + "; ".join(errors)
        )

