"""On-prem eventing adapter backed by Redis Pub/Sub."""

from __future__ import annotations

import json
import os
import uuid
from typing import Any, Optional

import redis

from shared.adapters.ports import EventingPort


class RedisEventing(EventingPort):
    """Eventing adapter using Redis Pub/Sub for on-prem deployments."""

    def __init__(self, *, redis_url: Optional[str] = None) -> None:
        url = redis_url or os.environ.get("REDIS_URL", "redis://localhost:6379/0")
        self._redis = redis.Redis.from_url(url, decode_responses=True)
        self._subscriptions: dict[str, str] = {}

    def publish(self, topic: str, message: str, attributes: Optional[dict[str, str]] = None) -> str:
        payload = json.dumps({"message": message, "attributes": attributes or {}})
        self._redis.publish(topic, payload)
        return uuid.uuid4().hex

    def subscribe(self, topic: str, callback_url_or_queue: str) -> str:
        sub_id = uuid.uuid4().hex
        self._subscriptions[sub_id] = f"{topic}:{callback_url_or_queue}"
        return sub_id

