"""On-prem secrets adapter backed by environment variables or a local encrypted file.

For simplicity and air-gap compatibility, this adapter reads secrets from
environment variables with a configurable prefix, or from a JSON file.
"""

from __future__ import annotations

import json
import os
from typing import Optional

from shared.adapters.ports import SecretsPort


class EnvFileSecrets(SecretsPort):
    """Secrets adapter that reads from env vars or a JSON secrets file.

    Lookup order:
      1. Environment variable ``{prefix}{secret_id}``
      2. JSON file at ``secrets_file_path``
      3. In-memory store (for put_secret during the process lifetime)
    """

    def __init__(
        self,
        *,
        env_prefix: str = "SECRET_",
        secrets_file_path: Optional[str] = None,
    ) -> None:
        self._env_prefix = env_prefix
        self._file_path = secrets_file_path or os.environ.get("SECRETS_FILE", "")
        self._memory: dict[str, str] = {}
        self._file_cache: Optional[dict[str, str]] = None

    def _load_file(self) -> dict[str, str]:
        if self._file_cache is None:
            if self._file_path and os.path.isfile(self._file_path):
                with open(self._file_path, "r") as fh:
                    self._file_cache = json.load(fh)
            else:
                self._file_cache = {}
        return self._file_cache

    def get_secret(self, secret_id: str) -> str:
        # 1. env var
        env_key = f"{self._env_prefix}{secret_id}".upper().replace("-", "_")
        val = os.environ.get(env_key)
        if val is not None:
            return val
        # 2. file
        file_secrets = self._load_file()
        if secret_id in file_secrets:
            return file_secrets[secret_id]
        # 3. memory
        if secret_id in self._memory:
            return self._memory[secret_id]
        raise KeyError(secret_id)

    def put_secret(self, secret_id: str, value: str) -> None:
        self._memory[secret_id] = value

