"""On-prem log-sink adapter backed by structured JSON file logging."""

from __future__ import annotations

import json
import logging
import os
from typing import Any, Optional

from shared.adapters.ports import LogSinkPort


class FileLogSink(LogSinkPort):
    """Log-sink adapter that writes structured JSON to a file or stdout."""

    def __init__(
        self,
        *,
        log_file: Optional[str] = None,
    ) -> None:
        self._log_file = log_file or os.environ.get("LOG_SINK_FILE", "")
        self._logger = logging.getLogger("shared.adapters.onprem.log_sink")
        if not self._logger.handlers:
            handler: logging.Handler
            if self._log_file:
                handler = logging.FileHandler(self._log_file)
            else:
                handler = logging.StreamHandler()
            handler.setFormatter(logging.Formatter("%(message)s"))
            self._logger.addHandler(handler)
            self._logger.setLevel(logging.DEBUG)
        self._buffer: list[dict[str, Any]] = []

    def emit(self, log_entry: dict[str, Any]) -> None:
        self._buffer.append(log_entry)
        if len(self._buffer) >= 25:
            self.flush()

    def flush(self) -> None:
        for entry in self._buffer:
            self._logger.info(json.dumps(entry))
        self._buffer.clear()

